 return {project_id:'probe',session_id:'a',observed_at:`2026-10-13T04:00:0${version}Z`,session_closed_at:null,plan:{event_cursor:version,head:{scope:{project_id:'probe',session_id:'a'},ref,status_revision:1,progress_cursor:0,status:'active',outcome:null},version:{scope:{project_id:'probe',session_id:'a'},ref,base:version===1?null:version-1,body:structuredClone(value),author:{scope:{project_id:'probe',session_id:'a'},role:'main',user_id:null,run_id:'synthetic',alias:null,resolved_model:null,tool_call:null,grant:null,track_id:null},reason:'Synthetic',recorded_at:at},steps:[{step_id:'step',step_sha256:'a'.repeat(64),matches_current_step:false,latest:null}]}};
}
